import { useDroppable } from "@dnd-kit/core";

import { cn } from "../../lib/cn";
import type { GroupEdgeDropData, PaneEdgeDropData, TabDropEdge } from "./tabDragTypes";

type SplitEdgeDropData = GroupEdgeDropData | PaneEdgeDropData;

type SplitEdgeDropZoneProps = {
  id: string;
  data: SplitEdgeDropData;
  edge: TabDropEdge;
  testId: string;
  groupId?: string;
  tabId?: string;
  leafId?: string;
};

/**
 * Shared split-edge target used by both tab drags and pane-handle drags.
 * Drag source only changes the command resolved after drop; target geometry and
 * visual feedback intentionally follow the same tab-drag contract.
 */
export function SplitEdgeDropZone({
  id,
  data,
  edge,
  testId,
  groupId,
  tabId,
  leafId,
}: SplitEdgeDropZoneProps) {
  const { setNodeRef, isOver } = useDroppable({ id, data });

  return (
    <div
      ref={setNodeRef}
      aria-hidden="true"
      data-testid={testId}
      data-split-edge-drop-zone="true"
      data-dnd-type={data.type}
      data-drop-edge={edge}
      data-drop-group-id={groupId}
      data-tab-id={tabId}
      data-leaf-id={leafId}
      className={cn(
        "pointer-events-none absolute z-40 transition-colors",
        edgeHitTargetClass(edge),
        isOver && "border-2 border-primary bg-primary/20 backdrop-blur-[1px]",
      )}
    >
      {isOver ? (
        <span
          data-testid="split-edge-drop-feedback"
          className="absolute bottom-2 left-2 rounded-sm bg-background/80 px-1.5 py-0.5 text-[10px] font-medium text-foreground shadow-sm"
        >
          New split
        </span>
      ) : null}
    </div>
  );
}

export function edgeHitTargetClass(edge: TabDropEdge): string {
  switch (edge) {
    case "left":
      return "inset-y-0 left-0 w-[20%]";
    case "right":
      return "inset-y-0 right-0 w-[20%]";
    case "top":
      return "left-[20%] right-[20%] top-0 h-[20%]";
    case "bottom":
      return "bottom-0 left-[20%] right-[20%] h-[20%]";
  }
}

import { cleanup, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";

const overIds = vi.hoisted(() => new Set<string>());

vi.mock("@dnd-kit/core", () => ({
  useDroppable: ({ id }: { id: string }) => ({
    setNodeRef: vi.fn(),
    isOver: overIds.has(id),
  }),
}));

import { SplitEdgeDropZone } from "./SplitEdgeDropZone";

afterEach(() => {
  cleanup();
  overIds.clear();
});

describe("SplitEdgeDropZone", () => {
  it("renders identical tab-style split feedback for group-edge and pane-edge targets", () => {
    overIds.add("group-edge:group-a:left");
    overIds.add("pane-edge:tab-a:leaf-a:left");

    render(
      <>
        <SplitEdgeDropZone
          id="group-edge:group-a:left"
          data={{ type: "group-edge", groupId: "group-a", edge: "left" }}
          edge="left"
          testId="group-edge"
          groupId="group-a"
        />
        <SplitEdgeDropZone
          id="pane-edge:tab-a:leaf-a:left"
          data={{ type: "pane-edge", tabId: "tab-a", leafId: "leaf-a", edge: "left" }}
          edge="left"
          testId="pane-edge"
          tabId="tab-a"
          leafId="leaf-a"
        />
      </>,
    );

    const groupEdge = screen.getByTestId("group-edge");
    const paneEdge = screen.getByTestId("pane-edge");
    expect(groupEdge.className).toBe(paneEdge.className);
    expect(groupEdge).toHaveAttribute("data-split-edge-drop-zone", "true");
    expect(paneEdge).toHaveAttribute("data-split-edge-drop-zone", "true");
    expect(groupEdge).toHaveClass("inset-y-0", "left-0", "w-[20%]");
    expect(paneEdge).toHaveClass("inset-y-0", "left-0", "w-[20%]");

    const feedback = screen.getAllByTestId("split-edge-drop-feedback");
    expect(feedback).toHaveLength(2);
    expect(feedback.map((node) => node.textContent)).toEqual(["New split", "New split"]);
    expect(feedback[0].className).toBe(feedback[1].className);
  });
});

import { invoke } from "@tauri-apps/api/core";
import type {
  BrowserSessionSummary,
  BrowserState,
  CreateBrowserRequest,
  LogicalRect,
} from "./types";

const browserLifecycleQueues = new Map<string, Promise<void>>();

function enqueueBrowserLifecycle(browserId: string, operation: () => Promise<void>): Promise<void> {
  const previous = browserLifecycleQueues.get(browserId) ?? Promise.resolve();
  const next = previous.catch(() => undefined).then(operation);
  browserLifecycleQueues.set(browserId, next);

  const clearIfCurrent = () => {
    if (browserLifecycleQueues.get(browserId) === next) {
      browserLifecycleQueues.delete(browserId);
    }
  };
  void next.then(clearIfCurrent, clearIfCurrent);

  return next;
}

export async function createBrowser(request: CreateBrowserRequest): Promise<BrowserState> {
  return invoke<BrowserState>("cmd_browser_create", { request });
}

export async function navigateBrowser(browserId: string, url: string): Promise<void> {
  return invoke<void>("cmd_browser_navigate", { browserId, url });
}

export async function reloadBrowser(browserId: string): Promise<void> {
  return invoke<void>("cmd_browser_reload", { browserId });
}

export async function setBrowserBounds(browserId: string, bounds: LogicalRect): Promise<void> {
  return invoke<void>("cmd_browser_set_bounds", { browserId, bounds });
}

export function setBrowserVisible(browserId: string, visible: boolean): Promise<void> {
  return enqueueBrowserLifecycle(browserId, () => invoke<void>("cmd_browser_set_visible", { browserId, visible }));
}

export async function setBrowserZoom(browserId: string, zoomFactor: number): Promise<number> {
  return invoke<number>("cmd_browser_set_zoom", { browserId, zoomFactor });
}

export async function focusBrowser(browserId: string): Promise<void> {
  return invoke<void>("cmd_browser_focus", { browserId });
}

export async function getBrowserState(browserId: string): Promise<BrowserState> {
  return invoke<BrowserState>("cmd_browser_get_state", { browserId });
}

export function closeBrowser(browserId: string): Promise<void> {
  return enqueueBrowserLifecycle(browserId, () => invoke<void>("cmd_browser_close", { browserId }));
}

export async function listBrowsers(): Promise<BrowserSessionSummary[]> {
  return invoke<BrowserSessionSummary[]>("cmd_browser_list");
}

export async function importBrowserCookies(profileId: string, filePath: string): Promise<number> {
  const result = await invoke<{ importedCount: number }>("cmd_browser_import_cookies", {
    request: { browserId: profileId, filePath },
  });
  return result.importedCount;
}

export async function openExternalUrl(url: string): Promise<void> {
  return invoke<void>("cmd_browser_open_external", { url });
}

import { useRef, useEffect } from "react";
import { setBrowserBounds, setBrowserVisible } from "../lib/browserTauri";
import { BrowserToolbar } from "./BrowserToolbar";
import type { BrowserTab } from "../lib/types";

interface BrowserPaneProps {
  tab: BrowserTab;
  visible?: boolean;
  onNavigate: (url: string) => void;
  onReload: () => void;
}

export function BrowserPane({ tab, visible = true, onNavigate, onReload }: BrowserPaneProps) {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const el = containerRef.current;
    if (!el) return;

    const updateVisibility = (nextVisible: boolean) => {
      void setBrowserVisible(tab.browserId, nextVisible).catch(() => undefined);
    };

    const updateBounds = () => {
      if (!visible) {
        updateVisibility(false);
        return;
      }

      const rect = el.getBoundingClientRect();
      void setBrowserBounds(tab.browserId, {
        x: rect.x,
        y: rect.y,
        width: rect.width,
        height: rect.height,
      }).catch(() => undefined);
      updateVisibility(true);
    };

    updateBounds();

    const resizeObserver = new ResizeObserver(() => {
      updateBounds();
    });

    resizeObserver.observe(el);
    window.addEventListener("resize", updateBounds);

    return () => {
      resizeObserver.disconnect();
      window.removeEventListener("resize", updateBounds);
      // Native child webviews outlive React DOM nodes; cleanup also covers Fast Refresh remounts.
      updateVisibility(false);
    };
  }, [tab.browserId, visible]);

  return (
    <div className="flex flex-col w-full h-full bg-background overflow-hidden">
      <BrowserToolbar tab={tab} onNavigate={onNavigate} onReload={onReload} />
      <div
        ref={containerRef}
        data-testid="browser-viewport"
        className="flex-1 w-full bg-card relative"
      />
    </div>
  );
}

import { render, waitFor } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";

import type { BrowserTab } from "../lib/types";
import { BrowserPane } from "./BrowserPane";

const browserMocks = vi.hoisted(() => ({
  setBrowserBounds: vi.fn(async () => undefined),
  setBrowserVisible: vi.fn(async () => undefined),
}));

vi.mock("../lib/browserTauri", () => browserMocks);
vi.mock("./BrowserToolbar", () => ({ BrowserToolbar: () => <div data-testid="browser-toolbar" /> }));

const tab: BrowserTab = {
  kind: "browser",
  id: "tab-browser",
  label: "Browser",
  browserId: "browser-1",
  url: "http://localhost:3000",
  loading: false,
  canGoBack: false,
  canGoForward: false,
};

describe("BrowserPane native webview lifecycle", () => {
  beforeEach(() => {
    browserMocks.setBrowserBounds.mockClear();
    browserMocks.setBrowserVisible.mockClear();
  });

  it("shows the child webview while mounted and hides it during cleanup", async () => {
    const { unmount } = render(
      <BrowserPane tab={tab} onNavigate={() => undefined} onReload={() => undefined} />,
    );

    await waitFor(() => {
      expect(browserMocks.setBrowserBounds).toHaveBeenCalledWith("browser-1", {
        x: 0,
        y: 0,
        width: 0,
        height: 0,
      });
      expect(browserMocks.setBrowserVisible).toHaveBeenCalledWith("browser-1", true);
    });

    unmount();

    await waitFor(() => {
      expect(browserMocks.setBrowserVisible).toHaveBeenLastCalledWith("browser-1", false);
    });
  });

  it("keeps an explicitly hidden child webview hidden", async () => {
    render(
      <BrowserPane tab={tab} visible={false} onNavigate={() => undefined} onReload={() => undefined} />,
    );

    await waitFor(() => {
      expect(browserMocks.setBrowserVisible).toHaveBeenCalledWith("browser-1", false);
    });
    expect(browserMocks.setBrowserBounds).not.toHaveBeenCalled();
  });
});

